import{_ as a,c as t,o,a2 as r}from"./chunks/framework.mqLGQ42V.js";const h=JSON.parse('{"title":"关键帧 (Keyframes) - Rive 编辑器","description":"关键帧允许你定义对象属性随时间的变化。这些变化在 Rive 引擎中被内插（Interpolated），从而产生平滑的运动。 你可以通过在动画模式 (Animate Mode) 下操作对象，或者使用检查器 (Inspector) 来设置关键帧。","frontmatter":{"title":"关键帧 (Keyframes) - Rive 编辑器","description":"关键帧允许你定义对象属性随时间的变化。这些变化在 Rive 引擎中被内插（Interpolated），从而产生平滑的运动。 你可以通过在动画模式 (Animate Mode) 下操作对象，或者使用检查器 (Inspector) 来设置关键帧。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 动画模式, 关键帧"}]]},"headers":[],"relativePath":"editor/animate-mode/keyframes.md","filePath":"editor/animate-mode/keyframes.md","lastUpdated":1774867914000}'),n={name:"editor/animate-mode/keyframes.md"};function i(d,e,p,s,m,l){return o(),t("div",null,[...e[0]||(e[0]=[r('<p>动画模式</p><h1 id="关键帧-keyframes" tabindex="-1">关键帧 (Keyframes) <a class="header-anchor" href="#关键帧-keyframes" aria-label="Permalink to &quot;关键帧 (Keyframes)&quot;">​</a></h1><p>关键帧允许你定义对象属性随时间的变化。这些变化在 Rive 引擎中被内插（Interpolated），从而产生平滑的运动。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 关键帧 Pn)</p></blockquote><h2 id="​-设置关键帧" tabindex="-1"><a href="#setting-keys">​</a> 设置关键帧 <a class="header-anchor" href="#​-设置关键帧" aria-label="Permalink to &quot;[​](#setting-keys) 设置关键帧&quot;">​</a></h2><p>你可以通过在动画模式 (Animate Mode) 下操作对象，或者使用检查器 (Inspector) 来设置关键帧。</p><p>在使用创建工具、变换工具或钢笔工具在舞台上操作对象时，任何更改都会自动在时间轴上设置关键帧。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 在舞台设置关键帧 Pn)</p></blockquote><p>你也可以通过点击检查器中属性右侧的菱形图标来设置关键帧。带有蓝色外框的菱形图标表示当前属性已在当前播放头位置设置了关键帧。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 在检查器设置关键帧 Pn)</p></blockquote><h2 id="​-插值-interpolation" tabindex="-1"><a href="#interpolation">​</a> 插值 (Interpolation) <a class="header-anchor" href="#​-插值-interpolation" aria-label="Permalink to &quot;[​](#interpolation) 插值 (Interpolation)&quot;">​</a></h2><p>插值决定了属性在两个关键帧之间如何变化。通过点击并拖拽时间轴上的关键帧，或在检查器中进行设置，你可以调整插值类型（如：线性、贝塞尔、保持等）。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 插值示例 Pn)</p></blockquote><h2 id="​-复制与粘贴关键帧" tabindex="-1"><a href="#copy-and-paste">​</a> 复制与粘贴关键帧 <a class="header-anchor" href="#​-复制与粘贴关键帧" aria-label="Permalink to &quot;[​](#copy-and-paste) 复制与粘贴关键帧&quot;">​</a></h2><p>你可以选中一个或多个关键帧，使用快捷键（<code>Cmd/Ctrl + C</code> 和 <code>Cmd/Ctrl + V</code>）在同一个时间轴或不同的时间轴之间进行复制粘贴。</p><p><a href="/docs/editor/animate-mode/timeline">时间轴 (Timeline)</a><a href="/docs/editor/animate-mode/settings">动画设置 (Settings)</a></p>',16)])])}const f=a(n,[["render",i]]);export{h as __pageData,f as default};
